  "bots.setup.callbackUrlTitle": "URL обратного вызова",
  "bots.setup.callbackUrlDescription.webhook":
    "Внешняя система должна отправлять callback входящих сообщений на этот адрес. Асинхронные исходящие ответы по-прежнему идут на Webhook URL, указанный слева.",
